body {
  margin: 0px;
}

.container {
  font-family: "Inter", "Segoe UI", Arial, sans-serif;
  width: 100%;
}

.info-grid {
  display: flex;
  gap: 40px;
  background: var(--dark-f2f3f5, var(--appsmith-theme-panelColor, #0f172a));
  border-radius: 5px;
  padding: 20px;
}

.info-column {
  width: 60%;
}

.info-row {
  display: flex;
  justify-content: space-between;
  padding: 6px 0;
}

.label {
  font-weight: 500;
  color: var(--dark-222222, var(--appsmith-theme-textStrongColor, #ffffff));
}

.value {
  font-weight: 600;
  color: var(--dark-111111, var(--appsmith-theme-textStrongColor, #ffffff));
  text-align: right;
}

.value:empty::after {
  content: "-";
  color: var(--dark-aaaaaa, var(--appsmith-theme-textMutedColor, #64748b));
}

